	/** 
	 * jumpstart the process by instantiating2 Registration
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		registrationId = RegistrationService.getRegistrationInstance()
		.createRegistration( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		RegistrationService.getRegistrationInstance()
				.createRegistration( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.registrationSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Registration : " + successValue.getRegistrationId());
							  if (successValue.getRegistrationId().equals(registrationId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRegistrationList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Registration test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on registration consumed")
					);
			subscriber.registrationSubscribe( registrationId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Registration : " + successValue.getRegistrationId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRegistrationList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on registration for registrationId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Registration. 
	 */
	protected Registration read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Registration" );

		Registration entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Registration with primary key" );
		msg.append( registrationId );
		
		RegistrationFetchOneSummary fetchOneSummary = new RegistrationFetchOneSummary( registrationId );

		try {
			entity = RegistrationService.getRegistrationInstance().getRegistration( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Registration " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Registration.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Registration." );

		StringBuilder msg = new StringBuilder( "Failed to update a Registration : " );        
		Registration entity = read();
		UpdateRegistrationCommand command = generateUpdateCommand();
		command.setRegistrationId(entity.getRegistrationId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Registration." );

			// for use later on...
			registrationId = entity.getRegistrationId();

			RegistrationService proxy = RegistrationService.getRegistrationInstance();  

			proxy.updateRegistration( command ).get();

			LOGGER.info( "-- Successfully saved Registration - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + registrationId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Registration.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Registration." );

		Registration entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Registration with id " + registrationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Registration with id " + registrationId );

			throw e;
		}

		try{
			RegistrationService.getRegistrationInstance().delete( new DeleteRegistrationCommand( entity.getRegistrationId() ) ).get();
			LOGGER.info( "-- Successfully deleted Registration with id " + registrationId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Registration with id " + registrationId );

			throw e;
		}
	}

	/**
	 * get all Registrations.
	 */
	protected List<Registration> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Registrations:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Registration : " );        
		List<Registration> collection  = new ArrayList<>();

		try {
			// call the static get method on the RegistrationService
			collection = RegistrationService.getRegistrationInstance().getAllRegistration();
			assertNotNull( collection, "An Empty collection of Registration was incorrectly returned.");
			
			// Now print out the values
			Registration entity = null;            
			Iterator<Registration> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRegistrationId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

